const normalizeMode = (mode?: string) => (mode || '').trim();

const inferGradeForMode = (mode: string): number | undefined => {
  const gradeMatch = mode.match(/_G(\d+)(?:_|$)/);
  if (gradeMatch) return Number(gradeMatch[1]);

  const numberedSubjectGradeMatch = mode.match(/^(?:SCIENCE|SOCIAL|LIFE)_(\d+)(?:_|$)/);
  if (numberedSubjectGradeMatch) return Number(numberedSubjectGradeMatch[1]);

  if (mode === 'ADD_1DIGIT' || mode === 'ADD_1DIGIT_CARRY' || mode === 'SUB_1DIGIT') return 1;
  if (mode === 'SUB_1DIGIT_BORROW' || mode === 'ADDITION' || mode === 'SUBTRACTION' || mode === 'MULTIPLICATION') return 2;
  if (mode === 'DIVISION' || mode === 'MIXED') return 3;

  const kanjiGradeMatch = mode.match(/^KANJI_(\d+)$/);
  if (kanjiGradeMatch) return Number(kanjiGradeMatch[1]);

  if (mode.startsWith('UPPER_') || mode.startsWith('HARD_KANJI') || mode.startsWith('KANKEN')) return 10;
  return undefined;
};

const replaceMany = (value: string, replacements: Array<[string, string]>) =>
  replacements.reduce((current, [from, to]) => current.split(from).join(to), value);

