const limitSummaryKanjiByGrade = (summary: UnitBoardSummary, grade?: number): UnitBoardSummary => ({
  ...summary,
  grade,
  title: gradeLimitedTitle(summary.title, grade),
  subtitle: gradeLimitedText(summary.subtitle, grade),
  goal: gradeLimitedText(summary.goal, grade),
  points: summary.points.map((point) => gradeLimitedText(point, grade)),
  mistakes: summary.mistakes.map((mistake) => gradeLimitedText(mistake, grade)),
  example: summary.example ? gradeLimitedText(summary.example, grade) : undefined,
});

const gradeLimitedTitle = (value: string, grade?: number) => {
  if (!grade || grade >= 4) return value;
  const titleReplacements: Array<[string, string]> = [
    ['算数・数学', grade <= 1 ? 'さんすう' : '算数'],
    ['算数', grade <= 1 ? 'さんすう' : '算数'],
    ['数学', grade <= 1 ? 'さんすう' : '数学'],
    ['たし算', grade <= 1 ? 'たしざん' : 'たし算'],
    ['ひき算', grade <= 1 ? 'ひきざん' : 'ひき算'],
    ['計算', grade <= 1 ? 'けいさん' : '計算'],
    ['図形', grade <= 1 ? 'かたち' : '図形'],
    ['順番', grade <= 2 ? 'じゅんばん' : '順番'],
    ['問題文', grade <= 2 ? 'もんだいぶん' : '問題文'],
    ['国語辞典', grade <= 3 ? '国語じてん' : '国語辞典'],
    ['辞典', grade <= 3 ? 'じてん' : '辞典'],
    ['使い方', grade <= 3 ? '使いかた' : '使い方'],
    ['読み取り', grade <= 3 ? '読みとり' : '読み取り'],
    ['書き方', grade <= 3 ? '書きかた' : '書き方'],
    ['見方', grade <= 3 ? '見かた' : '見方'],
    ['説明文', grade <= 3 ? 'せつめい文' : '説明文'],
    ['要点', grade <= 3 ? '大事なところ' : '要点'],
    ['段落', grade <= 3 ? 'まとまり' : '段落'],
    ['リスニング総仕上げ', grade <= 3 ? 'リスニングまとめ' : 'リスニング総仕上げ'],
    ['発声総仕上げ', grade <= 3 ? '声に出すまとめ' : '発声総仕上げ'],
    ['復唱問題総仕上げ', grade <= 3 ? 'まねして言う問題まとめ' : '復唱問題総仕上げ'],
    ['応答問題総仕上げ', grade <= 3 ? 'こたえる問題まとめ' : '応答問題総仕上げ'],
    ['英単語総合', grade <= 3 ? '英単語まとめ' : '英単語総合'],
  ];
  return replaceMany(value, titleReplacements);
};

const titleFromMode = (mode: string, unitLabel?: string) => {
  if (unitLabel?.trim()) return unitLabel.trim();
  if (BASIC_CALC_SUMMARIES[mode]) return BASIC_CALC_SUMMARIES[mode].title;

  const schoolSubjectMatch = mode.match(/^(MATH|KOKUGO|ENGLISH|SCIENCE|SOCIAL|LIFE)_G(\d+)(?:_U\d+|_\d+)?/);
  if (schoolSubjectMatch) {
    const grade = Number(schoolSubjectMatch[2]);
    const subjectNames: Record<string, string> = {
      MATH: grade <= 6 ? '算数' : '数学',
      KOKUGO: '国語',
      ENGLISH: '英語',
      SCIENCE: '理科',
      SOCIAL: '社会',
      LIFE: '生活',
    };
    return `${grade}年 ${subjectNames[schoolSubjectMatch[1]]}`;
  }

  return mode
    .replace(/^UPPER_/, '')
    .replace(/_/g, ' ')
    .toLowerCase()
    .replace(/\b\w/g, (char) => char.toUpperCase());
};

const genericKeyForMode = (mode: string): keyof typeof GENERIC_SUMMARIES | null => {
  if (/^(ADD|SUB|MULT|DIV|MIXED|MATH|UPPER_MATH)/.test(mode)) return 'math';
  if (/^(KOKUGO|UPPER_MODERN|UPPER_CLASSICS)/.test(mode)) return 'language';
  if (/^(KANJI|KANKEN|HARD_KANJI)/.test(mode)) return 'kanji';
  if (/^(ENGLISH|UPPER_ENGLISH)/.test(mode)) return 'english';
  if (/^(SCIENCE|LIFE|UPPER_SCIENCE)/.test(mode)) return 'science';
  if (/^(SOCIAL|MAP_|PREF_|PREFECTURES|UPPER_SOCIETY)/.test(mode) || /(GEOGRAPHY|HISTORY|CIVICS)/.test(mode)) return 'social';
  if (/^(IT_|UPPER_INFORMATION)/.test(mode)) return 'information';
  if (/^UPPER_ESSAY/.test(mode)) return 'essay';
  if (/^UPPER_PRACTICAL/.test(mode)) return 'practical';
  return null;
};

export const getUnitBoardSummary = (mode?: string, unitLabel?: string): UnitBoardSummary | null => {
  const normalizedMode = normalizeMode(mode);
  if (!normalizedMode && !unitLabel) return null;
  const grade = inferGradeForMode(normalizedMode);

  const exact = EXACT_SUMMARIES[normalizedMode];
  if (exact) {
    const summary = unitLabel && unitLabel !== exact.title
      ? { ...exact, id: `${exact.id}:${unitLabel}`, title: unitLabel }
      : exact;
    return limitSummaryKanjiByGrade(summary, grade);
  }

  const genericKey = genericKeyForMode(normalizedMode);
  if (!genericKey) return null;

  const generic = GENERIC_SUMMARIES[genericKey];
  const title = titleFromMode(normalizedMode, unitLabel);
  return limitSummaryKanjiByGrade({
    id: `${normalizedMode || genericKey}:${title}`,
    title,
    ...generic,
  }, grade);
};
